def pre(xs):
    return all(isinstance(x, int) for x in xs) and -9 <= x <= 9 for x in xs) and len(xs) <= 6

def post(xs, result):
    max_val = max(xs)
    distinct_values = set(xs)
    if len(distinct_values) < 2:
        return result is None
    second_largest = max((x for x in distinct_values if x != max_val), default=None)
    return result == second_largest

def helper_max(xs):
    if not xs:
        return -float('inf')
    return max(helper_max(xs[:-1]), xs[-1])
